// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }
    function testFuzz_property(uint256 amount, address from, address to) public {
        __InvMutHandleStub stub = __InvMutHandleStub(payable(address(c.share())));
        bool flag = (amount % 2 == 0);
        stub.setTransferFromReturn(flag);
        vm.prank(from);
        bool returned = c.transferFrom(from, to, amount);
        // General rule: c.transferFrom returns exactly the boolean value that the
        // underlying share token returned (here the stub's configured flag).
        assertTrue(returned == flag);
    }
}
contract __InvMutHandleStub {
    bool public transferFromReturn = true;
    function setTransferFromReturn(bool v) external { transferFromReturn = v; }
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
    function WETH() external view returns (address) { return address(this); }
    function name() external pure returns (string memory) { return "S"; }
    function symbol() external pure returns (string memory) { return "S"; }
    function decimals() external pure returns (uint8) { return 18; }
    function totalSupply() external pure returns (uint256) { return 0; }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function allowance(address, address) external pure returns (uint256) { return 0; }
    function approve(address, uint256) external pure returns (bool) { return true; }
    function transfer(address, uint256) external pure returns (bool) { return true; }
    function transferFrom(address, address, uint256) external view returns (bool) { return transferFromReturn; }
    receive() external payable {}
